import { sheetKey, useSheet } from './sheet';
import type { Sheet } from './sheet';

// The sheet's today: shown, and changeable. A change re-reads everything kept for the sheet, as
// whatever depends on the date may now read differently.
function SheetToday({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const sheet = useSheet(sheetId);
  const [input, setInput] = useState('');
  const [error, setError] = useState('');

  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today }),
    onSuccess: (updated) => {
      queryClient.setQueryData(sheetKey(sheetId), updated);
      void queryClient.invalidateQueries({
        queryKey: ['sheet', sheetId],
        predicate: (q) => q.queryKey[2] !== 'info',
      });
    },
    onError: () => setError('That date could not be set as today.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const today = input.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      setError('Choose a date for today.');
      return;
    }
    save.mutate(today);
  };

  return (
    <form onSubmit={submit} data-testid="sheet-today-form">
      Today: <strong data-testid="sheet-today">{sheet.data?.today ?? ''}</strong>{' '}
      <label>
        Set today{' '}
        <input
          type="date"
          data-testid="sheet-today-input"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set
      </button>
      {(error || sheet.isError) && (
        <p role="alert" data-testid="sheet-error">
          {error || 'The sheet could not be read.'}
        </p>
      )}
    </form>
  );
}

export const contribution = SheetBody.fill({ order: -100, Component: SheetToday });
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSheetId } from './session';

type Sheet = { id: string };

// Choose a sheet by typing its id and loading it. An id never used before starts an empty sheet;
// loading an id again drops what was cached for it, so the sheet is re-read from the store.
export function SheetLoader({ onLoaded }: { onLoaded: () => void }) {
  const queryClient = useQueryClient();
  const [sheetId, setSheetId] = useSheetId();
  const [input, setInput] = useState('');
  const [error, setError] = useState('');

  const load = useMutation({
    mutationFn: (id: string) => postJson<Sheet>(`/api/sheets/${encodeURIComponent(id)}/load`, {}),
    onSuccess: (sheet) => {
      queryClient.removeQueries({ queryKey: ['sheet', sheet.id] });
      setSheetId(sheet.id);
      onLoaded();
    },
    onError: () => setError('That sheet could not be loaded.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const id = input.trim();
    if (id === '') {
      setError('Type a sheet id to load.');
      return;
    }
    load.mutate(id);
  };

  return (
    <form onSubmit={submit} data-testid="sheet-form">
      <label>
        Sheet{' '}
        <input
          data-testid="sheet-id-input"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-load" disabled={load.isPending}>
        Load
      </button>{' '}
      {sheetId && (
        <span>
          Active sheet: <strong data-testid="sheet-current-id">{sheetId}</strong>
        </span>
      )}
      {error && (
        <p role="alert" data-testid="sheet-load-error">
          {error}
        </p>
      )}
    </form>
  );
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useUser } from './session';

// Sign in by typing a name; there is no password.
export function SignIn() {
  const [, setUser] = useUser();
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = name.trim();
    if (trimmed === '') {
      setError('Type a name to sign in.');
      return;
    }
    setError('');
    setUser(trimmed);
  };

  return (
    <form onSubmit={submit} data-testid="signin-form">
      <label>
        Name{' '}
        <input
          data-testid="signin-name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="signin-submit">
        Sign in
      </button>
      {error && (
        <p role="alert" data-testid="signin-error">
          {error}
        </p>
      )}
    </form>
  );
}
